package com.novalang.bukkit.types.event;
import com.novalang.bukkit.Requires; import com.novalang.bukkit.types.value.NovaTypeSupport; import com.novalang.runtime.host.JavaTypes; import java.util.Collection; import org.bukkit.event.player.PlayerChatTabCompleteEvent;
@Requires(classes = {"org.bukkit.event.player.PlayerChatTabCompleteEvent"}) public final class NovaPlayerChatTabCompleteEvent { private NovaPlayerChatTabCompleteEvent() { } public static void register(JavaTypes.Builder b){b.extension(PlayerChatTabCompleteEvent.class,"chatMessage",f->f.returns(String.class).invoke(a->event(a).getChatMessage()));b.extension(PlayerChatTabCompleteEvent.class,"lastToken",f->f.returns(String.class).invoke(a->event(a).getLastToken()));b.extension(PlayerChatTabCompleteEvent.class,"tabCompletions",f->f.returns(Collection.class).invoke(a->event(a).getTabCompletions()));}private static PlayerChatTabCompleteEvent event(Object[] a){return NovaTypeSupport.argument(a,0,PlayerChatTabCompleteEvent.class);}}
